import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"62、【小過】 艮下震上","description":"周易尚氏學 - 62、【小過】 艮下震上","frontmatter":{"title":"62、【小過】 艮下震上","description":"周易尚氏學 - 62、【小過】 艮下震上"},"headers":[],"relativePath":"classics/shangshi/067.md","filePath":"classics/shangshi/067.md"}'),s={name:"classics/shangshi/067.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_62、【小過】-艮下震上" tabindex="-1">62、【小過】 艮下震上 <a class="header-anchor" href="#_62、【小過】-艮下震上" aria-label="Permalink to “62、【小過】 艮下震上”">​</a></h1><p>過之為義。彖傳即不明釋。故訖無定解。後儒於是有以經過為說者。端木國瑚謂兌巽過乾之左右。故曰大過。艮震過坤之左右。故曰小過。有以過越為說者。朱震謂大過陽過陰。大者過越也。小過四陰二陽。小者過越也。前一說人只見於端木氏。後一說則易家多從之。然尚有五陽五陰之卦。何以不言過。且漢人以大過為死卦。陽過盛而反死。又何說乎。如謂四陽為上下二陰所束縛故死。則小過四陰包二陽。胡以不謂之死乎。又四陽在中為大過。四陰在中何以不謂為小過。而必以四陰在外者為小過乎。是皆可疑。而先儒無言者。按太玄擬大玄過為失。雲陰大作賊。陽不能得。言陽為阻賊。而失其用也。擬小過為羨為差。雲陽氣贊幽。推包羨爽。未得正行。言震陽本可直出。乃為上下四陰所包。推排曲抑。仍有羨爽。羨邪曲。爽差也。蓋大過按卦氣時當小雪。窮陰極寒。故陽氣極衰。小過時當立春。陽氣闢。本可無阻。乃為陰氣所包。仍不免小有回曲。大小過純以卦義言。不以陰陽多少言也。卦二五陰得中。二陰承重陽故亨。陰牝陽故利貞。陰得中故可小事。陽失位而不中。故不可大事。左傳昭五年。筮遇明夷之謙曰。日之謙當鳥。日之謙即離變艮。變艮而曰當鳥。是以艮為鳥。易林本之。以艮為黔啄為鳥。詳焦氏易詁小過下艮故曰鳥。上震故曰飛鳥。而震為覆艮。是上下皆鳥。故傳曰有飛鳥之象焉。宋衷謂二陽在內。上下各二陰。有似飛鳥舒翮之象。虞翻則用卦變。雲小過從晉來。晉上離為鳥。惠士奇謂古飛非通用。小過即非字象。故曰飛鳥。愈演愈寄。皆艮鳥象失傳之過也。遺送也。震為音。茹敦和雲。下艮為反震。口向下若送音於人者。故飛鳥遺之音。上謂五。五失位而乘陽。正謂二。二當位而承陽。故上不宜而下大吉也。</p><p>彖曰。小過。小者過而亨也。過以利貞。與時行也。柔得中。是以小事吉也。剛失位而不中。是以不可大事也。有飛鳥之象焉。飛鳥道之音。不宜上宜下。大吉。上邊而下順也。</p><p>艮為時。剛失位指四。不中指三。有飛鳥之象。謂上下卦皆艮也。非如宋衷之解。艮為鳥。上艮覆故曰逆。下反是故順。又五乘剛故逆。二承陽故順。</p><p>象曰。山上有雷。小過。君子以行過乎恭。</p><p>喪過乎哀。用過乎儉。震為行。恭或為艮象。兌毀折故曰喪。震為樂。震反為艮。故為哀。儉亦或為艮止象。舊解皆用卦變。無確詁。姑測其義如此。又三者皆過之微。即治小過之義也。</p><p>初六。飛鳥以兇。</p><p>艮為鳥。四雖有應。二得敵。應予阻格。又失位。故兇。</p><h3 id="象曰。飛鳥以兇。不可如何也。" tabindex="-1">象曰。飛鳥以兇。不可如何也。 <a class="header-anchor" href="#象曰。飛鳥以兇。不可如何也。" aria-label="Permalink to “象曰。飛鳥以兇。不可如何也。”">​</a></h3><p>言應困難。</p><p>六二。過其祖。遇其妣。不及其君。遇其臣，無咎。</p><p>艮為祖。二承三故過其祖。巽為妣。二當巽初。故遇其妣。爾雅母曰妣。妣謂二。祖謂三。二應在五。五震為君。乃五不應。故不及其君。良為臣。三艮主爻。二承之。故遇其臣。艮為祖。翼為母。震君艮臣象皆失傳。故舊解無通者。義詳焦氏易詁。</p><h3 id="象曰。不及其君。臣不可過也。" tabindex="-1">象曰。不及其君。臣不可過也。 <a class="header-anchor" href="#象曰。不及其君。臣不可過也。" aria-label="Permalink to “象曰。不及其君。臣不可過也。”">​</a></h3><p>傳義未詳。舊說或崑崙。或浮泛。皆不安。</p><p>九三。弗過防之。從或戕之。兇。</p><p>四遇敵故弗過。艮為守為堅。下有群陰承之。利於防守。故曰防之。與漸九三。蒙上九利禦寇。義同也。三應在上。戕害也。從或戕之者。言三若應上。則四或害之也。艮為刀劍。四艮反向下。故戕之。首回防之。所以戒也。</p><h3 id="象曰。從或戕之。兇何如也。" tabindex="-1">象曰。從或戕之。兇何如也。 <a class="header-anchor" href="#象曰。從或戕之。兇何如也。" aria-label="Permalink to “象曰。從或戕之。兇何如也。”">​</a></h3><p>極言其兇。</p><p>九四。無咎。弗過遇之。往厲必戒。匆用永貞。</p><p>四臨重阻。利往。故無咎。四應在初。遇謂遇三也。三為四敵。故戒以弗過。然而遇之。往厲者。謂往應初而厲也。往應初。則三戕之。故厲。厲則宜有所戒。勿用而貞定自守可也。無咎指上行。弗過指下行。昔賢皆泥於往外為往。豈知需上雲。三人來。是往外而日來。睽上雲。往遇雨。是來內而曰往。易團於往來不執定例也。</p><h3 id="象曰。弗過遇之。位不當也。往厲必戒。終不可長也。" tabindex="-1">象曰。弗過遇之。位不當也。往厲必戒。終不可長也。 <a class="header-anchor" href="#象曰。弗過遇之。位不當也。往厲必戒。終不可長也。" aria-label="Permalink to “象曰。弗過遇之。位不當也。往厲必戒。終不可長也。”">​</a></h3><p>言之初仍勿用為宜。終不可長。</p><p>六五。密雲不雨。自我西郊。公弋取彼在穴。</p><p>文言以坤為雲。五上重陰。故曰密雲。兌為雨。風火在下。故不雨。兌西震東。言此密雲起自西郊。而東行也。震為公為射。故曰公弋。七者繫繩於矢以射鳥。乃不射身而以上取彼在穴之艮狐。胡能得乎。蓋五應在二。二巽為繩。艮為矢。以繩系矢。七象也。而艮為穴為孤。艮手為取。穴居之物。豈能弋取。言二不應五。有如此也。凡易取象。不於本變必於應。應爻有應予。如明夷初交應在四震。則曰飛。曰翼。曰攸往。曰主人有言。全取震象。而直言之。應爻無應予。亦往往取其象而明其不應。如歸妹上六應在三兌。則曰女承筐。曰士圭（右刀）羊。女與羊皆兌象。而三不應上。故又曰無實無血。及此爻皆是也。舊解不知此例。見象無著。則用卦變以當之。於是易義遂亡於講說矣。</p><h3 id="象曰。密雲不雨。已上也。" tabindex="-1">象曰。密雲不雨。已上也。 <a class="header-anchor" href="#象曰。密雲不雨。已上也。" aria-label="Permalink to “象曰。密雲不雨。已上也。”">​</a></h3><p>巳上與小畜之上往同義。</p><p>上六。弗遇過之。飛鳥離之。兇。是謂災音。</p><p>弗遇言為五所格。應三難也。乃竟過之。是無心相值。不虞之禍。蓋艮為鳥。上卦艮覆。鳥首向下有墜象。而艮為刀兵。正墜兵刃之上。離罹通。道也。遭此意外之禍。故兇也。三巽體。巽為疾病。故為災眚。是謂災眚者。言禍非由己。致無妄之災。不可如何也。</p><h3 id="象曰。弗遇過之。巳亢也。" tabindex="-1">象曰。弗遇過之。巳亢也。 <a class="header-anchor" href="#象曰。弗遇過之。巳亢也。" aria-label="Permalink to “象曰。弗遇過之。巳亢也。”">​</a></h3><p>虞翻雲。飛下稱亢。按說文。亢人頸。或從頁。是亢即頏。古通為一字。詩邶風頜之頏之。毛傳飛而上曰頡。飛而下回頏。故前書揚雄傳解嘲。鄒行以頡亢而取世資。頏即作亢。師古云。頡亢上下不定也。亦訓亢為下。上卦艮鳥覆有墜象。故曰亢。已亢者。言飛鳥離災而下也。李道平雲。陽言亢。陰不言亢。故虞不從俗說。聞見錄雲。唐張師為贊皇尉。夢白鳥飛翔墜於雲際。召黃賀筮之。遇小過。曰。雷震山上。鳥墜雲間。聲跡兩銷。不可復見。委心順命可也。是亦以艮為鳥。艮覆故曰鳥墜。互大坎故曰云間。震為聲跡。坎隱伏。故曰聲道兩銷。不可復見。是亢之為下。再見於唐人所釋。以艮覆為鳥墜。黃賀獨知也。</p>',30)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
